func (s *Store) ListReleaseRecordHistory(environment string, afterRecordedAt string, afterID int64, limit int) ([]ReleaseRecord, error) {
	query := `SELECT r.id, r.` + strings.ReplaceAll(releaseRecordColumns, ", ", ", r.") +
